@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource/dm-mono/400.css";
@import "@fontsource/dm-mono/500.css";
@import "@fontsource/encode-sans-expanded/600.css";
@import "@fontsource/encode-sans-expanded/700.css";

/* Light: the sibling. A pale workshop grey page, navy ink and navy hairlines, the same gold
   for labels and the solid button, the richer blue where the dark mode uses sky blue. */
:root {
  --background: oklch(0.964 0 0);
  --foreground: oklch(0.262 0.077 251.3);
  --card: oklch(0.928 0 0);
  --card-foreground: oklch(0.262 0.077 251.3);
  --popover: oklch(0.985 0 0);
  --popover-foreground: oklch(0.262 0.077 251.3);
  --primary: oklch(0.77 0.165 72.3);
  --primary-foreground: oklch(0.15 0 0);
  --secondary: oklch(0.928 0 0);
  --secondary-foreground: oklch(0.262 0.077 251.3);
  --muted: oklch(0.9 0.012 250);
  --muted-foreground: oklch(0.5 0.03 250);
  --accent: oklch(0.262 0.077 251.3 / 6%);
  --accent-foreground: oklch(0.262 0.077 251.3);
  --destructive: oklch(0.58 0.22 27);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.262 0.077 251.3);
  --input: oklch(0.262 0.077 251.3 / 40%);
  --ring: oklch(0.368 0.094 253.1);
  --highlight: oklch(0.368 0.094 253.1);
  --highlight-foreground: oklch(0.985 0 0);
  --glow: oklch(0.763 0.123 248.8);
  --chart-1: oklch(0.77 0.165 72.3);
  --chart-2: oklch(0.368 0.094 253.1);
  --chart-3: oklch(0.6 0.11 250);
  --chart-4: oklch(0.262 0.077 251.3);
  --chart-5: oklch(0.633 0 0);
  --sidebar: oklch(0.928 0 0);
  --sidebar-foreground: oklch(0.262 0.077 251.3);
  --sidebar-primary: oklch(0.262 0.077 251.3);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.262 0.077 251.3 / 6%);
  --sidebar-accent-foreground: oklch(0.262 0.077 251.3);
  --sidebar-border: oklch(0.262 0.077 251.3 / 30%);
  --sidebar-ring: oklch(0.368 0.094 253.1);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Encode Sans Expanded", "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "DM Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  --page-width: 90rem;
  --page-gutter: 1rem;
  --section-y: 6rem;
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 3.75rem;
    --section-y: 9rem;
  }
}

/* Dark: the faithful mode. Navy #002548 page, white ink, gold #f3a000, sky blue #70b8fd
   frames, rich blue #14406f behind media, white hairlines. */
.dark {
  --background: oklch(0.262 0.077 251.3);
  --foreground: oklch(1 0 0);
  --card: oklch(0.368 0.094 253.1);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.215 0.063 251);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.77 0.165 72.3);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.319 0.092 255.1);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.42 0.06 250);
  --muted-foreground: oklch(0.683 0.029 250);
  --accent: oklch(1 0 0 / 6%);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.65 0.22 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0);
  --input: oklch(1 0 0 / 40%);
  --ring: oklch(0.763 0.123 248.8);
  --highlight: oklch(0.763 0.123 248.8);
  --highlight-foreground: oklch(0.262 0.077 251.3);
  --glow: oklch(0.763 0.123 248.8);
  --chart-1: oklch(0.77 0.165 72.3);
  --chart-2: oklch(0.763 0.123 248.8);
  --chart-3: oklch(0.55 0.1 252);
  --chart-4: oklch(0.928 0 0);
  --chart-5: oklch(0.633 0 0);
  --sidebar: oklch(0.215 0.063 251);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.77 0.165 72.3);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(1 0 0 / 6%);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 20%);
  --sidebar-ring: oklch(0.763 0.123 248.8);
}
